import { existsSync } from "node:fs";
import { randomBytes } from "node:crypto";
import { defineConfig, devices, chromium } from "@playwright/test";
const existingBaseURL = process.env.MAILLOOP_E2E_BASE_URL;
const billingFixtureEnv = {
  DODO_PAYMENTS_ENVIRONMENT: "test_mode",
  DODO_PAYMENTS_API_KEY: "[REDACTED_SECRET]",
  DODO_PAID_MONTHLY_PRODUCT_ID: "pdt_browser_fixture",
  DODO_PAYMENTS_BUSINESS_ID: "bus_browser_fixture",
  DODO_PAYMENTS_WEBHOOK_KEY:
    process.env.DODO_PAYMENTS_API_KEY === "browser-fixture-not-an-api-key"
      ? process.env.DODO_PAYMENTS_WEBHOOK_KEY!
      : "whsec_" + randomBytes(32).toString("base64"),
  DODO_PAYMENTS_BASE_URL: "",
  DODO_PAYMENTS_CUSTOM_HEADERS: "",
  APP_ORIGIN: "http://localhost:3100",
};
// Share a fixture secret with the workers and Playwright-owned server. Never
// inherit real payment credentials into that server or change environment files.
if (!existingBaseURL) Object.assign(process.env, billingFixtureEnv);
export default defineConfig({
  testDir: "tests/browser",
  reporter: [["list"], ["html", { open: "never" }]],
  fullyParallel: false,
  workers: 1,
  timeout: 60000,
  use: {
    timezoneId: "Asia/Kolkata",
    actionTimeout: 10000,
    baseURL: existingBaseURL ?? "http://localhost:3100",
    trace: "retain-on-failure",
    screenshot: "only-on-failure",
    launchOptions: {
      executablePath:
        process.env.CHROME_PATH ??
        (existsSync("/opt/google/chrome/chrome")
          ? "/opt/google/chrome/chrome"
          : chromium.executablePath()),
    },
  },
  projects: [
    { name: "desktop", use: { ...devices["Desktop Chrome"] } },
    {
      name: "mobile",
      use: { ...devices["iPhone 13"], defaultBrowserType: "chromium" },
    },
  ],
  webServer: existingBaseURL
    ? undefined
    : {
        command: "npm run dev -- --port 3100",
        url: "http://localhost:3100",
        reuseExistingServer: false,
        timeout: 120000,
        env: {
          ...billingFixtureEnv,
          AUTH_URL: "http://localhost:3100",
          AUTH_TRUST_HOST: "true",
          INNGEST_DEV: "1",
          INNGEST_BASE_URL: "http://127.0.0.1:1",
        },
      },
});
